            if p.get("in") == "header" and p.get("name") == "x-project-id":
                continue
            print("  param", p.get("in"), p.get("name"), "required" if p.get("required") else "", shape(p.get("schema", {})))
        body = op.get("requestBody")
        if body:
            body = resolve(body)
            for ct, spec in body.get("content", {}).items():
