@dataclass
class Manifest:
    group_id: str
    webhook_id: str | None
    detections: dict[str, Binding]
    metrics: list[MetricReceptor]
    provisioned_at: str

    def save(self, path: Path) -> Path:
        path.parent.mkdir(parents=True, exist_ok=True)
        data = {
            "group_id": self.group_id,
            "webhook_id": self.webhook_id,
            "provisioned_at": self.provisioned_at,
            "detections": {k: vars(v) for k, v in sorted(self.detections.items())},
            "metrics": [vars(m) for m in self.metrics],
        }
        path.write_text(json.dumps(data, indent=1) + "\n", encoding="utf-8", newline="\n")
        return path

    @classmethod
    def load(cls, path: Path) -> Manifest:
        data = json.loads(path.read_text(encoding="utf-8"))
        return cls(
            group_id=data["group_id"],
            webhook_id=data.get("webhook_id"),
            detections={k: Binding(**v) for k, v in data["detections"].items()},
            metrics=[MetricReceptor(**m) for m in data["metrics"]],
            provisioned_at=data["provisioned_at"],
        )


class Provisioner:
    def __init__(self, api: Any) -> None:
        self.api = api
        self.created: list[str] = []
        self.deactivated: list[str] = []

    def group(self, name: str = GROUP_NAME) -> str:
        for group in self.api.detection_groups():
            if group.get("name") == name:
                return group["id"]
        made = self.api.create_detection_group(name, idempotency_key=content_key("group", name))
        self.created.append(f"group {name}")
        return made["id"]

    def webhook(self, url: str, secret: str, *, name: str = WEBHOOK_NAME) -> str:
        """Create or repoint the ingress webhook (the destination URL is redacted on read)."""
        body = {"destinationUrl": url, "secret": secret, "eventTypes": list(EVENT_TYPES)}
        for hook in self.api.webhooks():
            if hook.name == name:
                self.api.update_webhook(hook.id, body, idempotency_key=content_key("wh", body))
                if not hook.enabled:
                    self.api.set_webhook_status(hook.id, True)
                return hook.id
        made = self.api.create_webhook(name, url, EVENT_TYPES, secret=secret,
                                       idempotency_key=content_key("wh-new", name, body))  # fmt: skip
        self.created.append(f"webhook {name}")
        return made.id

    def ensure(self, desired: Plan | None = None, *, webhook_id: str | None = None) -> Manifest:
        group_id = self.group()
        desired = desired or plan(group_id=group_id)
        existing = {d.display_name: d for d in self.api.detections(group_id=group_id)}
        rules = {r.name: r for r in self.api.alert_rules()}
        bindings: dict[str, Binding] = {}
        wanted = {p.name for p in desired.detections}
        for item in desired.detections:
            body = {**item.detection, "groupId": group_id}
            found = existing.get(item.name)
            if found is None:
                found = self.api.create_detection(body, idempotency_key=content_key("det", body))
                self.created.append(item.name)
            elif not found.is_active:
                self.api.set_detection_status(found.id, True)
            alert = {**item.alert, "detectionId": found.id}
            if webhook_id:
                alert["channelMask"] = {"email": False, "slack": False, "webhookIds": [webhook_id]}
            rule = rules.get(alert["name"])
            if rule is None:
                rule = self.api.create_alert_rule(alert, idempotency_key=content_key("rule", alert))
                self.created.append(alert["name"])
            bindings[found.id] = Binding(found.id, item.receptor, item.host, item.version, rule.id)
        for name, stale in existing.items():
            if name not in wanted and stale.is_active:
                self.api.set_detection_status(stale.id, False)
                self.deactivated.append(name)
        stamp = datetime.now(UTC).strftime("%Y-%m-%dT%H:%M:%SZ")
        return Manifest(group_id, webhook_id, bindings, list(desired.metrics), stamp)

"""Invariant I7 (completeness) and the primitive of audit check C9 (spec §4.1.7, §7.5).

Every detection hit inside the window W must map to the ledger: either it **opened** an incident
or it was **attached** to one (a dedupe), as recorded in ``seen_hits``. A hit that neatlogs
reports but Omega never claimed is *missing*; a claimed hit with no decision is *pending*. Either
fails I7. The check is a pure function over the hits neatlogs reports and the store's rows, so
the audit can run it online (hits from the API) or offline (hits from a published bundle).
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field
from datetime import datetime

from kintsugi.senses.store import SeenHit, hit_key


@dataclass(frozen=True)
class ReportedHit:
    detection_id: str
    trace_id: str
    span_id: str
    detected_at: datetime

    @property
    def key(self) -> str:
        return hit_key(self.detection_id, self.trace_id, self.span_id)


@dataclass
class CompletenessReport:
    start: datetime
    end: datetime
    total: int = 0
    incidents: set[str] = field(default_factory=set)
    opened: int = 0
    attached: int = 0
    pending: list[str] = field(default_factory=list)
    missing: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.pending and not self.missing

    def summary(self) -> str:
        verdict = "PASS" if self.ok else "FAIL"
        return (f"{self.total} hits → {len(self.incidents)} incidents + {self.attached} dedupes"
                f" ({len(self.pending)} pending, {len(self.missing)} missing) {verdict}")  # fmt: skip


def completeness(
    reported: Iterable[ReportedHit],
    seen: Mapping[str, SeenHit],
    start: datetime,
    end: datetime,
) -> CompletenessReport:
    report = CompletenessReport(start, end)
    keys: set[str] = set()
    for hit in reported:
        if not start <= hit.detected_at < end or hit.key in keys:
            continue
        keys.add(hit.key)
        report.total += 1
        row = seen.get(hit.key)
        if row is None:
            report.missing.append(hit.key)
        elif row.incident is None or row.disposition is None:
            report.pending.append(hit.key)
        else:
            report.incidents.add(row.incident)
            if row.disposition == "opened":
                report.opened += 1
            else:
                report.attached += 1
    return report


def reported_hits(api: object, detection_ids: Iterable[str], start: datetime) -> list[ReportedHit]:
    """Every hit neatlogs reports for ``detection_ids`` detected at or after ``start``."""
    out: list[ReportedHit] = []
    for detection_id in detection_ids:
        for hits, _page in api.hit_pages(detection_id):  # type: ignore[attr-defined]
            out.extend(ReportedHit(detection_id, h.trace_id, h.span_id, h.detected_at)
                       for h in hits)  # fmt: skip
            if hits and min(h.detected_at for h in hits) < start:
                break
    return out

